import{_ as a,o as n,c as e,a4 as s}from"./chunks/framework.BRzJ4ijD.js";const u=JSON.parse('{"title":"12. 多模态: 跨注意力 / Flamingo / LLaVA / BLIP-2 / 扩散多模态","description":"","frontmatter":{},"headers":[],"relativePath":"ai-ml/multimodal.md","filePath":"ai-ml/multimodal.md","lastUpdated":1788475713000}'),i={name:"ai-ml/multimodal.md"};function r(o,t,l,d,h,p){return n(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="_12-多模态-跨注意力-flamingo-llava-blip-2-扩散多模态" tabindex="-1">12. 多模态: 跨注意力 / Flamingo / LLaVA / BLIP-2 / 扩散多模态 <a class="header-anchor" href="#_12-多模态-跨注意力-flamingo-llava-blip-2-扩散多模态" aria-label="Permalink to &quot;12. 多模态: 跨注意力 / Flamingo / LLaVA / BLIP-2 / 扩散多模态&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>Transformer 让语言有了统一的&quot;token → embedding → attention&quot;骨架，多模态只剩两件事：<strong>把别的模态编码成向量序列</strong>、<strong>想办法把它和语言对齐</strong>。这一章把三大代表路线讲透：(1) ** reservation-based**（ViT 把图像切块当 token 直接进 LLM，LLaVA）；(2) <strong>cross-attention</strong>（在 LLM 中插额外 K/V 接图像特征，Flamingo / BLIP-2）；(3) <strong>diffusion-based</strong>（文本→图像/视频/音频，Stable Diffusion / DiT）。它们是 GPT-4V / Gemini / Claude-V / Claude-3.5-Sonnet / 多模态 RAG / Sora / 语音模型背后的同一组抽象。</p><p>读完应能：</p><ol><li>区分 reservation-based（拼接）vs cross-attention（旁路）两种多模态接入方式，并说出各自取舍。</li><li>讲清 ViT 怎么把图像变成&quot;token 序列&quot;，CLIP 已在 §10 学过，知道它怎么给多模态做对齐。</li><li>说清 LLaVA / BLIP-2 / Flamingo 的训练数据分布（预训练 + 指令微调）和各自的选择。</li><li>看 Stable Diffusion 的 <code>文本 → UNet → 去噪图像</code> 能说清它和纯扩散的差别在哪，DiT 即 diffusion-on-Transformer 是当前主路。</li><li>给一个产品场景（VQA / 多模态 RAG / 视频理解 / TTS+ASR）选合适的架构。</li></ol><hr><h2 id="一、为何-多模态-变成一个问题" tabindex="-1">一、为何&quot;多模态&quot;变成一个问题 <a class="header-anchor" href="#一、为何-多模态-变成一个问题" aria-label="Permalink to &quot;一、为何&quot;多模态&quot;变成一个问题&quot;">​</a></h2><h3 id="_1-1-语言-vs-视觉信号的张力" tabindex="-1">1.1 语言 vs 视觉信号的张力 <a class="header-anchor" href="#_1-1-语言-vs-视觉信号的张力" aria-label="Permalink to &quot;1.1 语言 vs 视觉信号的张力&quot;">​</a></h3><ul><li>语言：高度离散 + 强语义 + 序列天然。一个 token ≈ 一个语义单元。</li><li>视觉：连续 + 弱语义 + 二维空间关系强。一个像素 ≈ 几乎没语义。</li><li>音频：一维时间序列 + 频域分析友好，每 10-20 ms 一个 frame。</li></ul><p>把视觉塞进 LLM 的本质问题：<strong>用什么粒度切？怎么映射到 embedding？怎么让 LLM 愿意去&quot;读&quot;它？</strong></p><h3 id="_1-2-三条主路" tabindex="-1">1.2 三条主路 <a class="header-anchor" href="#_1-2-三条主路" aria-label="Permalink to &quot;1.2 三条主路&quot;">​</a></h3><table tabindex="0"><thead><tr><th>路线</th><th>代表</th><th>怎么接</th></tr></thead><tbody><tr><td><strong>Reservation-based / 早期融合</strong></td><td>LLaVA, Qwen-VL, Intern-VL</td><td>图像切成 patch → 编码 → 当作额外 token <strong>拼在文本 prompt 前面</strong></td></tr><tr><td><strong>Cross-attention / 旁路</strong></td><td>Flamingo, BLIP-2</td><td>LLM 不动，<strong>在 Transformer block 之间插一层 cross-attn</strong> 接图像特征</td></tr><tr><td><strong>Diffusion-based</strong></td><td>Stable Diffusion, DiT, Sora</td><td>文本做 conditionUNet/DiT 的去噪过程，反向过程生成图像 / 视频 / 音频</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>还存在第四条更激进的「tokenizer 路线」: 用 VQ-VAE 把图像/音频 диск化成一个真正的离散词表（如 VQGAN），直接套 LLM 自回归——ESLM / AudioLM / VQGAN-Transformer / Parti 走这条。它统一但训练数据贵，本章末尾会点一下。</p></div><hr><h2 id="二、vit-图像-→-token-序列" tabindex="-1">二、ViT：图像 → token 序列 <a class="header-anchor" href="#二、vit-图像-→-token-序列" aria-label="Permalink to &quot;二、ViT：图像 → token 序列&quot;">​</a></h2><h3 id="_2-1-patchify" tabindex="-1">2.1 Patchify <a class="header-anchor" href="#_2-1-patchify" aria-label="Permalink to &quot;2.1 Patchify&quot;">​</a></h3><p>ViT（Dosovitskiy 2020）做了一件极简的事：<strong>像 NLP 切 token 一样切图像块</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>原图 H × W × C</span></span>
<span class="line"><span>   └─ 切 P×P 的 patch</span></span>
<span class="line"><span>       → 数量 N = (H/P) × (W/P)</span></span>
<span class="line"><span>       → 每个 patch 拉平 (P*P*C) 维向量</span></span>
<span class="line"><span>       → 线性映射到 D 维</span></span>
<span class="line"><span>       → 加上位置编码 (sin/cos 或 RoPE)</span></span>
<span class="line"><span>       → 进 Transformer Encoder (就是 BERT 那一套)</span></span></code></pre></div><p>示例：224×224 图，P=16，得到 14×14 = 196 个 patch，每个 768 维 → 一个长度 196 的&quot;图像句子&quot;。</p><h3 id="_2-2-与-§3、§10-的接" tabindex="-1">2.2 与 §3、§10 的接 <a class="header-anchor" href="#_2-2-与-§3、§10-的接" aria-label="Permalink to &quot;2.2 与 §3、§10 的接&quot;">​</a></h3><ul><li>ViT 的 self-attention 与 <a href="./transformer">§3 Transformer</a> 完全同构，只是把&quot;token = word&quot;换成&quot;token = image patch&quot;。</li><li>与 <a href="./contrastive-learning">§10 CLIP</a> 配合：ViT 是 CLIP 视觉分支，CLIP 训练确保 ViT 输出的 embedding 与文本对齐。</li></ul><h3 id="_2-3-spot-问题-分辨率与序列长度" tabindex="-1">2.3 spot 问题：分辨率与序列长度 <a class="header-anchor" href="#_2-3-spot-问题-分辨率与序列长度" aria-label="Permalink to &quot;2.3 spot 问题：分辨率与序列长度&quot;">​</a></h3><ul><li>图像切完细粒度 patch，token 数随分辨率二次方涨：448×448 → 28×28 = 784 patch；高分辨率图 token 列完后轻易几千。</li><li>高分辨率方案： <ul><li><strong>动态切片 / AnyRes</strong>：只在物体所在的格子切 patch，整体 token 数下降。</li><li><strong>token 聚合 / pooling</strong>：把 4 个相邻 patch 合一个。</li><li><strong>读懂的 adapter</strong>：如 Q-Former（BLIP-2）把 256patch 摘要到 32 个 query token。</li></ul></li></ul><hr><h2 id="三、reservation-based-路线-llava" tabindex="-1">三、reservation-based 路线：LLaVA <a class="header-anchor" href="#三、reservation-based-路线-llava" aria-label="Permalink to &quot;三、reservation-based 路线：LLaVA&quot;">​</a></h2><h3 id="_3-1-最小骨架" tabindex="-1">3.1 最小骨架 <a class="header-anchor" href="#_3-1-最小骨架" aria-label="Permalink to &quot;3.1 最小骨架&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LLM (Vicuna / LLaMA / Qwen) ── 标准 Transformer</span></span>
<span class="line"><span>   ▲</span></span>
<span class="line"><span>   │ 图像 token 拼在前面</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>ViT (CLIP 视觉分支) → projection MLP → image tokens</span></span></code></pre></div><p>伪代码：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> llava_forward</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(image, text_prompt):</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    img_feat </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> vit(image)                       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># [N_patch, D_v]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    img_tok  </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> projector(img_feat)              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># [N_patch, D_llm]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    txt_tok  </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tokenizer(text_prompt)           </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># [T, D_llm]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    seq      </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cat([img_tok, txt_tok, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 拼成一条</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> llm(seq)                             </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 标准 LLM</span></span></code></pre></div><h3 id="_3-2-训练两阶段" tabindex="-1">3.2 训练两阶段 <a class="header-anchor" href="#_3-2-训练两阶段" aria-label="Permalink to &quot;3.2 训练两阶段&quot;">​</a></h3><ol><li><strong>预训练对齐</strong>（projection MLP）：用图文对（如 LAION-CCN / CC3M），<strong>冻结 LLM 和 ViT</strong>，只学 projection——目标 next-token CE，让 LLM 学会读 image token。</li><li><strong>指令微调</strong>（LLM + projection）：用 GPT-4 生成的视觉指令数据（LLaVA-Instruct），解冻 LLM，让模型学会&quot;看图答题&quot;。</li></ol><h3 id="_3-3-取舍" tabindex="-1">3.3 取舍 <a class="header-anchor" href="#_3-3-取舍" aria-label="Permalink to &quot;3.3 取舍&quot;">​</a></h3><ul><li>✅ 极简、复用已有 LLM（不动 attention 结构）、贡献就是 projection + 数据。</li><li>✅ 指令微调几乎和纯文本 SFT 同构 → 工程上友好。</li><li>❌ 图像 token 占主上下文（高分辨率图成千 token），挤占有效文本长度。</li><li>❌ 对视频、长序列（数千帧）不友好 → 后续 Qwen-VL / Intern-VL 加分辨率自适应 + token 聚合。</li></ul><hr><h2 id="四、cross-attention-路线-flamingo-blip-2" tabindex="-1">四、Cross-attention 路线：Flamingo / BLIP-2 <a class="header-anchor" href="#四、cross-attention-路线-flamingo-blip-2" aria-label="Permalink to &quot;四、Cross-attention 路线：Flamingo / BLIP-2&quot;">​</a></h2><h3 id="_4-1-思路-llm-不动-加旁路" tabindex="-1">4.1 思路：LLM 不动，加旁路 <a class="header-anchor" href="#_4-1-思路-llm-不动-加旁路" aria-label="Permalink to &quot;4.1 思路：LLM 不动，加旁路&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LLM block (decoder-only)</span></span>
<span class="line"><span>   ├─ self-attn (原有)</span></span>
<span class="line"><span>   └─ cross-attn (新加一层)</span></span>
<span class="line"><span>         K, V ← image features</span></span>
<span class="line"><span>         Q    ← self-attn 输出的 hidden</span></span></code></pre></div><p>每 N 个 block 插一层 cross-attn，让 LLM &quot;看一眼图像特征&quot;。</p><h3 id="_4-2-flamingo-2022" tabindex="-1">4.2 Flamingo（2022） <a class="header-anchor" href="#_4-2-flamingo-2022" aria-label="Permalink to &quot;4.2 Flamingo（2022）&quot;">​</a></h3><ul><li>Perceiver Resampler：把任意形状的视觉特征（几千 patch）压成 32 个 latent token——这就是 §5.3 那一类 token 聚合更彻底版本。</li><li>Gated cross-attn：cross-attn 的输出去 zero-init + gated，<strong>训练开始时纯走 LLM 不被噪声拉偏</strong>，再逐渐打开 gate——同一思想也用在 <a href="./transformer">§3 残差初始化</a>。</li><li>用 Interleaved image-text 数据训练（图文交错，比 paired 多得多）。</li></ul><h3 id="_4-3-blip-2-2023-q-former" tabindex="-1">4.3 BLIP-2（2023）：Q-Former <a class="header-anchor" href="#_4-3-blip-2-2023-q-former" aria-label="Permalink to &quot;4.3 BLIP-2（2023）：Q-Former&quot;">​</a></h3><p>BLIP-2 的&quot;Q-Former&quot;是一个小 Transformer，<strong>32 个可学习的 query token 去抽 image feature</strong>——可类比 retrieval 的 query，但是是 token-level。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Frozen image encoder (ViT-G)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>Q-Former (32 learnable queries)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>32 个 image token → projection → 拼到 LLM prompt 前面 OR 喂 cross-attn</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>Frozen LLM (OPT / FlanT5)</span></span></code></pre></div><p>Q-Former 两阶段训练：(1) 一阶段 vision-language 对比 + 生成 +图文匹配；(2) 接 LLM 学生成。</p><h3 id="_4-4-cross-attn-vs-reservation-取舍" tabindex="-1">4.4 Cross-attn vs Reservation 取舍 <a class="header-anchor" href="#_4-4-cross-attn-vs-reservation-取舍" aria-label="Permalink to &quot;4.4 Cross-attn vs Reservation 取舍&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>Reservation (LLaVA)</th><th>Cross-attn (Flamingo / BLIP-2)</th></tr></thead><tbody><tr><td>改 LLM 结构</td><td>不改</td><td>加层</td></tr><tr><td>上下文消耗</td><td>占主窗口（图越多越挤）</td><td>几乎不挤</td></tr><tr><td>训练成本</td><td>高（LLM 要微调）</td><td>可冻 LLM</td></tr><tr><td>灵活性</td><td>全参数微调，迁移性强</td><td>多任务接入要重新设计 gate</td></tr><tr><td>视频/多图</td><td>不友好</td><td>更友好（Perceiver Resampler）</td></tr></tbody></table><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>选型口诀：<strong>要 zero-shot 多模态、上下文压得紧 → cross-attn 路线；要全力微调下游任务、不在乎 token 数 → reservation 路线。</strong> 实际生产里两者越来越融合，例如 Qwen-VL 在 reservation 基础上加 dynamic patch + 摘要，把 cross-attn 的&quot;省 token&quot;优点偷了过来。</p></div><hr><h2 id="五、扩散多模态-stable-diffusion-dit-sora" tabindex="-1">五、扩散多模态：Stable Diffusion / DiT / Sora <a class="header-anchor" href="#五、扩散多模态-stable-diffusion-dit-sora" aria-label="Permalink to &quot;五、扩散多模态：Stable Diffusion / DiT / Sora&quot;">​</a></h2><h3 id="_5-1-复习-§5-扩散模型" tabindex="-1">5.1 复习 §5 扩散模型 <a class="header-anchor" href="#_5-1-复习-§5-扩散模型" aria-label="Permalink to &quot;5.1 复习 §5 扩散模型&quot;">​</a></h3><p>回顾 <a href="./generative">§5 generative</a>：扩散模型 = <strong>加噪 → 学反向去噪</strong>。生成时从纯噪声开始，一步步去回原图。</p><h3 id="_5-2-文本条件怎么进" tabindex="-1">5.2 文本条件怎么进 <a class="header-anchor" href="#_5-2-文本条件怎么进" aria-label="Permalink to &quot;5.2 文本条件怎么进&quot;">​</a></h3><p><strong>Conditioning</strong>：把文本编码后注入 UNet 的去噪过程。三个层次：</p><table tabindex="0"><thead><tr><th>层次</th><th>做法</th></tr></thead><tbody><tr><td>全局 cond 向量</td><td>把 CLIP 文本 embedding <code>c</code> 加到 UNet 的中间层（class-conditional 那套）</td></tr><tr><td>Cross-attention</td><td>文本 token 作为 K/V，图像 feature 作为 Q——和 §4 Flamingo 一模一样</td></tr><tr><td>T5 / CLIP 双 stack</td><td>SDXL / SD3 用两个文本 encoder 拼出更丰富的 condition</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>多模态扩散里文本不是模型&quot;输入&quot;，而是<strong>去噪过程的 condition</strong>——文本和图像通过 cross-attn 在每一步去噪时交互。这和 LLaVA 的&quot;拼在前面&quot;是不同的耦合方式。</p></div><h3 id="_5-3-dit-用-transformer-替代-unet" tabindex="-1">5.3 DiT：用 Transformer 替代 UNet <a class="header-anchor" href="#_5-3-dit-用-transformer-替代-unet" aria-label="Permalink to &quot;5.3 DiT：用 Transformer 替代 UNet&quot;">​</a></h3><p>DiT（Diffusion Transformer, Peebles &amp; Xie 2023）的核心改动：<strong>把 UNet 的卷积块换成 Transformer block</strong>——self-attn 处理 latent patch + cross-attn 接文本。</p><ul><li>训练好的 scaling：DiT-XL/2 在 ImageNet 给出比 UNet 更好的 FID/CLIP。</li><li>是 <strong>Sora</strong> 的底座：视频被编码成 latent 的 时空 patch 序列，DiT 一次性生成。</li></ul><h3 id="_5-4-latent-diffusion-stable-diffusion-的-latent-含义" tabindex="-1">5.4 Latent Diffusion（Stable Diffusion 的&quot;latent&quot;含义） <a class="header-anchor" href="#_5-4-latent-diffusion-stable-diffusion-的-latent-含义" aria-label="Permalink to &quot;5.4 Latent Diffusion（Stable Diffusion 的&quot;latent&quot;含义）&quot;">​</a></h3><p>不在像素空间去噪（512×512×3 太大），而是在 <code>VAE encoder</code> 把图像压到 64×64×4 的 latent，去噪过程在 latent 上进行，最后 VAE decoder 还原像素。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>image ──VAE-enc──► latent z (64×64×4)</span></span>
<span class="line"><span>                       │</span></span>
<span class="line"><span>              diffusion 在 z 上做去噪</span></span>
<span class="line"><span>                       │</span></span>
<span class="line"><span>                   z_clean</span></span>
<span class="line"><span>                       │</span></span>
<span class="line"><span>                  VAE-dec</span></span>
<span class="line"><span>                       │</span></span>
<span class="line"><span>                     image</span></span>
<span class="line"><span>文本 condition 通过 cross-attn 注入去噪网络</span></span></code></pre></div><h3 id="_5-5-失败模式与对策" tabindex="-1">5.5 失败模式与对策 <a class="header-anchor" href="#_5-5-失败模式与对策" aria-label="Permalink to &quot;5.5 失败模式与对策&quot;">​</a></h3><table tabindex="0"><thead><tr><th>现象</th><th>原因</th><th>对策</th></tr></thead><tbody><tr><td>多手多脚</td><td>长文细编码不足 + 采样 step 太少</td><td>增加 text encoder 容量、用 SDXL 的 dual encoder、提高 sampling step</td></tr><tr><td>文本不跟随</td><td>CLIP 文本 embedding 抽象级别太高、condition 强度低</td><td>用 T5 + classifier-free guidance 提高 condition 权重</td></tr><tr><td>构图坏</td><td>无 spatial 约束</td><td>ControlNet / layout-to-image 加空间条件</td></tr><tr><td>视频时间不稳</td><td>各帧独立去噪</td><td>加时间维度的 3D DiT + 视频专用 dataset</td></tr></tbody></table><hr><h2 id="六、视频-音频-跨模态生成" tabindex="-1">六、视频 / 音频 / 跨模态生成 <a class="header-anchor" href="#六、视频-音频-跨模态生成" aria-label="Permalink to &quot;六、视频 / 音频 / 跨模态生成&quot;">​</a></h2><h3 id="_6-1-视频" tabindex="-1">6.1 视频 <a class="header-anchor" href="#_6-1-视频" aria-label="Permalink to &quot;6.1 视频&quot;">​</a></h3><ul><li><strong>Sora / Video Diffusion</strong>：DiT 在 时空 latent patch 上做去噪，关键设计：spatial-temporal tokenizer 把视频 cron 化为三维 latent，attention 同时跨空间 + 跨时间。</li><li><strong>长视频一致性</strong>：靠&quot;前 N 帧作为 condition 短去噪出后续几帧&quot;（rollout-conditioned），与 <a href="./generative">AR 采样</a> 的 cache 一个道理。</li><li><strong>运动 controlled 生成</strong>：Motion Brush / DragNUWA 等用关键点作为额外 condition。</li></ul><h3 id="_6-2-音频-tts-asr-互为孪生" tabindex="-1">6.2 音频：TTS / ASR 互为孪生 <a class="header-anchor" href="#_6-2-音频-tts-asr-互为孪生" aria-label="Permalink to &quot;6.2 音频：TTS / ASR 互为孪生&quot;">​</a></h3><ul><li><strong>TTS</strong>（文字 → 音频）：现代系统用 <code>audio codec</code>（EnCodec / SoundStream）把音频变成离散 token，然后<strong>用 LLM 自回归地预测下一 audio token</strong>——VALL-E / SpearTTS / Voicebox。</li><li><strong>ASR</strong>（音频 → 文字）：whisper 用 encoder-decoder Transformer，encoder 处理音频的 mel-spectrogram，decoder 出 token；它就是 §3 的 Encoder-Decoder 派。</li><li><strong>统一语音对话</strong>：GPT-4o / Gemini Live 把 TTS + LLM + ASR 联合训，让端到端语音对话不像&quot;先用 ASR → LLM → TTS 三段管线&quot;那样延迟过大。</li></ul><h3 id="_6-3-跨模态检索-clip-已经做了一半" tabindex="-1">6.3 跨模态检索：CLIP 已经做了一半 <a class="header-anchor" href="#_6-3-跨模态检索-clip-已经做了一半" aria-label="Permalink to &quot;6.3 跨模态检索：CLIP 已经做了一半&quot;">​</a></h3><p>CLIP 把图文塞进同一空间。同理可以做&quot;音频-文本&quot;（CLAP）、&quot;视频-文本&quot;（VideoCLIP）、&quot;code-自然语言&quot;（Byteword embeddings）。核心都是 §10 InfoNCE + 配对数据。</p><hr><h2 id="七、多模态训练数据-从配对到指令" tabindex="-1">七、多模态训练数据：从配对到指令 <a class="header-anchor" href="#七、多模态训练数据-从配对到指令" aria-label="Permalink to &quot;七、多模态训练数据：从配对到指令&quot;">​</a></h2><h3 id="_7-1-三类数据" tabindex="-1">7.1 三类数据 <a class="header-anchor" href="#_7-1-三类数据" aria-label="Permalink to &quot;7.1 三类数据&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>用途</th><th>代表</th></tr></thead><tbody><tr><td><strong>配对</strong>（image-caption）</td><td>对齐预训练</td><td>LAION-5B / CC3M / CC12M</td></tr><tr><td><strong>交错</strong>（interleaved image-text）</td><td>学会&quot;在文本中插图像&quot;的语境</td><td>OBELICS / Multimodal-C4</td></tr><tr><td><strong>指令 / VQA</strong>（problem-solution）</td><td>学任务感</td><td>LLaVA-Instruct / VQAv2 / OK-VQA</td></tr></tbody></table><h3 id="_7-2-数据质量决定上限" tabindex="-1">7.2 数据质量决定上限 <a class="header-anchor" href="#_7-2-数据质量决定上限" aria-label="Permalink to &quot;7.2 数据质量决定上限&quot;">​</a></h3><ul><li><strong>caption 噪声大</strong>：网页爬的 alt-text 不一定描述图——多模型自蒸馏（用 LLaVA 生成生成 caption 训新 LLaVA）。</li><li><strong>指令数据少</strong>：人工造贵 → 让 GPT-4 / Claude 看图生问答对。</li><li><strong>极长尾概念</strong>：罕见场景（医学影像、工业缺陷）需要领域微调，不是通用模型能搞定的。</li></ul><h3 id="_7-3-与-§8-rlhf-的接" tabindex="-1">7.3 与 §8 RLHF 的接 <a class="header-anchor" href="#_7-3-与-§8-rlhf-的接" aria-label="Permalink to &quot;7.3 与 §8 RLHF 的接&quot;">​</a></h3><ul><li><strong>多模态 RLHF</strong>：用人类偏好对 (image, prompt, response_chosen / response_rejected) 做 DPO/PPO，和文本 RLHF 完全同构（参考 §8 DPO 公式）。</li><li><strong>RLHF-Curious</strong>：让 VLM 主动选 informative 图像生成，类似 Active Learning。</li></ul><hr><h2 id="八、多模态-rag-让-vlm-用上-图像知识库" tabindex="-1">八、多模态 RAG：让 VLM 用上&quot;图像知识库&quot; <a class="header-anchor" href="#八、多模态-rag-让-vlm-用上-图像知识库" aria-label="Permalink to &quot;八、多模态 RAG：让 VLM 用上&quot;图像知识库&quot;&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>query (text)</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>retriever (跨模态 embedding, CLIP-based)</span></span>
<span class="line"><span>   │ 从 image+text 库检索 K 个最相关候选</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>VLM 读 K 张图 + 原文 → answer</span></span></code></pre></div><ul><li>与文本 RAG 唯一的区别：retriever 是 CLIP / BLIP-2 这种跨模态 embedding。</li><li>工程挑战：图像 embedding 大、索引要在 <a href="./../databases/optimization/vectorized">pgvector</a> / Milvus / Qdrant 这种高维索引上做。</li><li>适用：医学问答、技术文档检索（带图表）、法务合同扫描件检索。</li></ul><hr><h2 id="九、benchmark-与评估" tabindex="-1">九、Benchmark 与评估 <a class="header-anchor" href="#九、benchmark-与评估" aria-label="Permalink to &quot;九、Benchmark 与评估&quot;">​</a></h2><h3 id="_9-1-视觉理解-benchmark" tabindex="-1">9.1 视觉理解 benchmark <a class="header-anchor" href="#_9-1-视觉理解-benchmark" aria-label="Permalink to &quot;9.1 视觉理解 benchmark&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名字</th><th>测什么</th></tr></thead><tbody><tr><td>VQAv2</td><td>通用视觉问答</td></tr><tr><td>GQA</td><td>推理 + 关系</td></tr><tr><td>OK-VQA</td><td>需要外部知识的 VQA</td></tr><tr><td>MMMU</td><td>多学科、本科难度的多模态</td></tr><tr><td>MathVista</td><td>数学题带图表</td></tr><tr><td>MMBench / MME</td><td>多维度 VQA 综合</td></tr><tr><td>DocVQA</td><td>文档 OCR + 推理</td></tr></tbody></table><h3 id="_9-2-生成评测" tabindex="-1">9.2 生成评测 <a class="header-anchor" href="#_9-2-生成评测" aria-label="Permalink to &quot;9.2 生成评测&quot;">​</a></h3><ul><li><strong>FID</strong>（Fréchet Inception Distance）：生成图像分布 vs 真实图像分布的距离（用 Inception-V3 抽 feature）。</li><li><strong>CLIP Score</strong>：生成图 + 提示文本的 CLIP 相似度。</li><li><strong>人类评测</strong>：DALL-E / Midjourney 论文标配的人类 preference 比较。</li><li><strong>Video metric</strong>：FVD（Fréchet Video Distance），跟 FID 同思路但捕捉时序。</li></ul><h3 id="_9-3-陷阱-vlm-的-hallucination" tabindex="-1">9.3 陷阱：VLM 的 hallucination <a class="header-anchor" href="#_9-3-陷阱-vlm-的-hallucination" aria-label="Permalink to &quot;9.3 陷阱：VLM 的 hallucination&quot;">​</a></h3><ul><li><strong>虚假对象</strong>：VLM&quot;看到&quot;图里没有的物体（POPE benchmark 专测这个）。</li><li><strong>固执偏置</strong>：图里只有一只猫，VLM 说&quot;两只猫在玩&quot;——LM 强先验压过视觉。</li><li><strong>位置推理差</strong>：左右、上下、前后极易错，研究者故意造 hard benchmark（GQA spatial）。</li></ul><hr><h2 id="十、与前面章节的接口表" tabindex="-1">十、与前面章节的接口表 <a class="header-anchor" href="#十、与前面章节的接口表" aria-label="Permalink to &quot;十、与前面章节的接口表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>接口</th><th>提供什么</th><th>本部分怎么用</th></tr></thead><tbody><tr><td><a href="./transformer">§3 Transformer</a></td><td>self-attn / cross-attn / MHA / encoder-decoder</td><td>ViT、cross-attn 路线、ASR/TTS 端到端</td></tr><tr><td><a href="./generative">§5 generative</a></td><td>扩散 / ELBO / AR</td><td>多模态扩散、视频生成</td></tr><tr><td><a href="./contrastive-learning">§10 contrastive</a></td><td>InfoNCE / CLIP zero-shot</td><td>多模态对齐预训练、跨模态 retrieval</td></tr><tr><td><a href="./tokenizer">§7 tokenizer</a></td><td>BPE / VQ 离散化</td><td>audio codec / VQ-VAE 把图像/音频 token 化</td></tr><tr><td><a href="./training-at-scale">§9 training-at-scale</a></td><td>长 context / 大 batch</td><td>ViT 大分辨率训练、视频 diffusion 训练显存</td></tr><tr><td><a href="./agents">§11 agents</a></td><td>tool use / code interpreter</td><td>多模态 agent（看网页图、生成图、读图表）</td></tr><tr><td><a href="./../info-theory/entropy">info-theory</a></td><td>互信息 / 率失真</td><td>latent diffusion 的 VAE 率失真 + 多模态对齐的互信息下界</td></tr><tr><td><a href="./../databases/optimization/vectorized">DB vector</a></td><td>pgvector / vector 索引</td><td>multimodal RAG 的 retrieval</td></tr><tr><td><a href="./../crypto/zkp">crypto/zkp</a></td><td>隐私计算</td><td>medical multimodal RAG 隐私 + 隐私审计</td></tr></tbody></table><hr><h2 id="十一、速查表-结束" tabindex="-1">十一、速查表 / 结束 <a class="header-anchor" href="#十一、速查表-结束" aria-label="Permalink to &quot;十一、速查表 / 结束&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>一页快速唤回：</p><ul><li><strong>ViT</strong>：图像切成 N 个 patch → 768 维 embedding → 进 Transformer（和 NLP 同构）。</li><li><strong>reservation based (LLaVA)</strong>：image token 拼在 prompt 前 → 改动少 + 训练简单。</li><li><strong>cross-attn (Flamingo / BLIP-2)</strong>：LLM 不动 + 旁路 cross-attn → 省上下文 + 可冻 LLM。</li><li><strong>Q-Former / Perceiver Resampler</strong>：把上千 image feature 摘要成 32 个 token。</li><li><strong>Stable Diffusion</strong>：latent diffusion + 文本做 condition（cross-attn）在 UNet/DiT 去噪。</li><li><strong>DiT</strong>：把 UNet 换 Transformer block，scaling 友好，Sora 的底座。</li><li><strong>TTS/ASR</strong>：audio codec 把音频 token 化 → LLM 自回归；whisper 是 encoder-decoder。</li><li><strong>多模态 RAG</strong>：CLIP 系 retriever + VLM reader；和文本 RAG 只差 retriever。</li><li><strong>数据三件套</strong>：配对 caption → 对齐；交错 image-text → 语境；VQA 指令 → 任务。</li><li><strong>评估</strong>：FID/CLIP-Score（生成），VQA/MMMU/MathVista（理解），POPE（防幻觉）。</li></ul></div><hr><p>下一篇: <a href="./../_meta/">元抽象卷 · 跨章节大主题</a>.</p>`,99)])])}const g=a(i,[["render",r]]);export{u as __pageData,g as default};
